window.LOGO_DATA = {
  'sodic-logo': 'data:image/png;base64,',
  'ogami-logo': 'data:image/png;base64,',
  'east-vale-logo': 'data:image/png;base64,',
  'sodic-east-logo': 'data:image/png;base64,',
};
function handleAssetFallback(img) {
  if (!img) return;
  var fallbacks = img.getAttribute('data-fallbacks');
  var logoKey = img.getAttribute('data-logo-key');
  var curIndex = parseInt(img.getAttribute('data-fallback-index') || '0', 10);
  
  if (fallbacks) {
    var list = fallbacks.split(',').map(function(s) { return s.trim(); }).filter(Boolean);
    if (curIndex < list.length) {
      img.setAttribute('data-fallback-index', curIndex + 1);
      img.src = list[curIndex];
      return;
    }
  }
  
  if (logoKey && window.LOGO_DATA && window.LOGO_DATA[logoKey]) {
    img.onerror = null;
    img.src = window.LOGO_DATA[logoKey];
  }
}
window.handleAssetFallback = handleAssetFallback;
